package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_createBeanDeserializer_TriageGen2Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private DeserializationConfig config;
    private JavaType type;
    private BeanDescription beanDesc;
    private TypeFactory typeFactory;

    // A dummy bean class for testing
    public static class TestBean {
        public String name;
    }

    // A dummy exception class for testing
    public static class TestException extends RuntimeException {}

    // An abstract class for testing materialization
    public static abstract class AbstractBean {
        public String value;
    }

    public static class ConcreteBean extends AbstractBean {}

    @Before
    public void setUp() {
        // Since BeanDeserializerFactory constructor takes DeserializerFactoryConfig, 
        // we mock the factory or use a spy to bypass protected method complexities if necessary.
        // However, the prompt implies testing the logic of the method itself.
        factory = Mockito.spy(new BeanDeserializerFactory(null));
        ctxt = mock(DeserializationContext.class);
        config = mock(DeserializationConfig.class);
        typeFactory = TypeFactory.defaultInstance();

        when(ctxt.getConfig()).thenReturn(config);

        type = typeFactory.constructType(TestBean.class);
        beanDesc = mock(BeanDescription.class);
    }

    /**
     * Test Case 1: Custom deserializer is found via _findCustomBeanDeserializer
     */
    @Test
    public void testCreateBeanDeserializer_ReturnsCustomDeserializer() throws JsonMappingException {
        JsonDeserializer<Object> customDeser = new StdDeserializer<Object>(Object.class) {};
        doReturn(customDeser).when(factory)._findCustomBeanDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(customDeser, result);
        verify(factory, never()).buildThrowableDeserializer(any(), any(), any());
    }

    /**
     * Test Case 2: Type is a Throwable, should call buildThrowableDeserializer
     */
    @Test
    public void testCreateBeanDeserializer_IsThrowable() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        JavaType exceptionType = typeFactory.constructType(TestException.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        doReturn(expectedDeser).when(factory).buildThrowableDeserializer(ctxt, exceptionType, beanDesc);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, exceptionType, beanDesc);

        assertEquals(expectedDeser, result);
    }

    /**
     * Test Case 3: Type is Abstract and can be materialized
     */
    @Test
    public void testCreateBeanDeserializer_MaterializeAbstractType() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        JavaType abstractType = typeFactory.constructType(AbstractBean.class);
        JavaType concreteType = typeFactory.constructType(ConcreteBean.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        doReturn(null).when(factory).buildThrowableDeserializer(any(), any(), any());
        doReturn(concreteType).when(factory).materializeAbstractType(ctxt, abstractType, beanDesc);
        when(config.introspect(concreteType)).thenReturn(beanDesc);
        doReturn(expectedDeser).when(factory).buildBeanDeserializer(ctxt, concreteType, beanDesc);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, abstractType, beanDesc);

        assertEquals(expectedDeser, result);
    }

    /**
     * Test Case 4: Type is Abstract but materialization returns null
     */
    @Test
    public void testCreateBeanDeserializer_AbstractButNoMaterialization() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        JavaType abstractType = typeFactory.constructType(AbstractBean.class);

        doReturn(null).when(factory).buildThrowableDeserializer(any(), any(), any());
        doReturn(null).when(factory).materializeAbstractType(ctxt, abstractType, beanDesc);

        // Should fall through to findStdDeserializer
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());
        // Mock isPotentialBeanType to return false for the abstract type's raw class
        doReturn(false).when(factory).isPotentialBeanType(AbstractBean.class);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, abstractType, beanDesc);

        assertNull(result);
    }

    /**
     * Test Case 5: Standard deserializer is found via findStdDeserializer
     */
    @Test
    public void testCreateBeanDeserializer_ReturnsStdDeserializer() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        JsonDeserializer<Object> stdDeser = mock(JsonDeserializer.class);

        doReturn(null).when(factory).buildThrowableDeserializer(any(), any(), any());
        doReturn(stdDeser).when(factory).findStdDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(stdDeser, result);
    }

    /**
     * Test Case 6: Not a standard deserializer, but is a potential bean type
     */
    @Test
    public void testCreateBeanDeserializer_ReturnsBeanDeserializer() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(null).when(factory).buildThrowableDeserializer(any(), any(), any());
        doReturn(null).when(factory).materializeAbstractType(any(), any(), any());
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());

        doReturn(true).when(factory).isPotentialBeanType(TestBean.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);
        doReturn(expectedDeser).when(factory).buildBeanDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(expectedDeser, result);
    }

    /**
     * Test Case 7: Not a standard deserializer and NOT a potential bean type
     */
    @Test
    public void testCreateBeanDeserializer_ReturnsNullIfNoPotentialBean() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(null).when(factory).buildThrowableDeserializer(any(), any(), any());
        doReturn(null).when(factory).materializeAbstractType(any(), any(), any());
        doReturn(null).when(factory).findStdDeserializer(any(), any(), any());

        // String is usually handled by StdDeserializer, so we use a type that isn't a bean
        JavaType stringType = typeFactory.constructType(String.class);
        doReturn(false).when(factory).isPotentialBeanType(String.class);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, stringType, beanDesc);

        assertNull(result);
    }
}
